INSERT INTO langs (Id, French) VALUES (9010000, 'Coffre du Chevalier de Glace'),
 (9010001, 'Ce coffre s''est retrouvé gelé par ce qui s''y cache à l''intérieur.'),
 (9010002, 'Fragment de carte du Chevalier de Glace 1/8'),
 (9010003, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010004, 'Fragment de carte du Chevalier de Glace 2/8'),
 (9010005, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010006, 'Fragment de carte du Chevalier de Glace 3/8'),
 (9010007, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010008, 'Fragment de carte du Chevalier de Glace 4/8'),
 (9010009, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010010, 'Fragment de carte du Chevalier de Glace 5/8'),
 (9010011, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010012, 'Fragment de carte du Chevalier de Glace 6/8'),
 (9010013, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010014, 'Fragment de carte du Chevalier de Glace 7/8'),
 (9010015, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010016, 'Fragment de carte du Chevalier de Glace 8/8'),
 (9010017, 'Ce fragment vous permettra de reconstituer la carte du Chevalier de Glace.'),
 (9010018, 'Carte du Chevalier de Glace'),
 (9010019, 'Cette carte vous permettra de trouver le trésor légendaire du Chevalier de Glace.'),
 (9010020, 'Fragment d''anomalie'),
 (9010021, 'Ces petites gemmes ressemblant à des miroirs semblent refléter des événements importants ayant pris place au sein d''autres époques. Espérons que les ramener sur le Plan Matériel n''ait aucun impact néfaste sur l''équilibre du Krosmoz.'),
 (9010022, 'Galet rayonnant'),
 (9010023, 'Ce caillou aux reflets dorés pourrait vous rendre riche, à défaut de mettre un peu de soleil dans votre vie.'),
 (9010024, 'Slip feuillu de Supervizœuf'),
 (9010025, 'Des zoologues audacieux ont prétendu que la feuille qui orne le devant de ce slip n''est pas vraiment une feuille... Simple hypothèse scientifique ou réalité ? La douleur ressentie par le Supervizœuf quand vous lui avez arraché son pagne est peut-être un élément de réponse.'),
 (9010026, 'Carapace de Supervizœuf'),
 (9010027, 'Avec son épaisse carapace de chitine, le Supervizœuf a des allures de boufbowler. Néanmoins, il est peu probable qu''on le voie un jour disputer un match à la loyale : il se ferait sans doute exclure pour exclosions intempestives.'),
 (9010028, 'Toison de la Déchireuse'),
 (9010029, 'Selon une tradition désuète, mais encore très populaire parmi les Léosas, la chevelure représente la position dans la hiérarchie des chasseuses. La toison de la Déchireuse est si brillante, si éclatante qu''il n''y a aucun doute quant à sa place au sommet. Qu''importe ce que vous déciderez d''en faire, veillez à y accorder le plus grand respect, car elle est le symbole d''une immense puissance.'),
 (9010030, 'Corne du Vénérable Endormi'),
 (9010031, 'Une fois assemblées, ces lourdes cornes pourraient former un puissant arc de chasse. Qu''est-ce qu''un grand singe aurait fait avec une telle arme ?'),
 (9010032, 'Coiffe de Bouflouth'),
 (9010033, 'Comme Bouflouth, vous pourrez vous ruer sur vos adversaires sans problème avec cette coiffe.'),
 (9010034, 'Amulette de Bouflouth'),
 (9010035, 'La corne de Bouflouth est très tranchante, l''avoir autour du cou peut se retourner très rapidement contre son porteur.'),
 (9010036, 'Ceinture de Bouflouth'),
 (9010037, 'Cette ceinture peut très certainement vous tenir chaud, mais ses cornes la rendent aussi très inconfortable.'),
 (9010038, 'Chaîne de Monsieur Pingouin'),
 (9010039, 'Durant sa jeunesse, Monsieur Pingouin n''était pas le Mansot qui glissait le plus loin sur la banquise. Cette chaîne n''a rien à voir avec tout cela, mais vous êtes maintenant au courant.'),
 (9010040, 'Sangle de Monsieur Pingouin'),
 (9010041, 'Avec cette sangle, vous serez manchic.'),
 (9010042, 'Palmes de Monsieur Pingouin'),
 (9010043, 'Ces palmes sont souvent portées par des individus qui ne sont pas manchots.'),
 (9010044, 'Cape de Katigrou'),
 (9010045, 'Avec cette cape, vous serez, vous aussi, un tigre.'),
 (9010046, 'Pattes de Katigrou'),
 (9010047, 'Certains Frigostiens font la promotion de ces bottes avec un bol de frostiz dans les mains, allez savoir pourquoi...'),
 (9010048, 'Mitaine de Katigrou'),
 (9010049, 'En observant cette mitaine, vous vous rappelez ce pain perdu que vous avez subi dans la forêt des pins perdus.'),
 (9010050, 'Voile de Fantômayte'),
 (9010051, 'Avec ce voile, vous aurez toujours aussi froid dans le dos.'),
 (9010052, 'Collier de Fantômayte'),
 (9010053, 'Ce qui ressemble à un petit fantôme dans ce collier essaie toujours de communiquer avec son propriétaire. Lorsqu''on le rapproche de son oreille, on peut y entendre un petit son, "Boooouwu !".'),
 (9010054, 'Bracelet de Fantômayte'),
 (9010055, 'Ce bracelet peut sembler à première vue banal, mais le petit fantôme qui s''y est enroulé peut s''avérer être un véritable couteau suisse.'),
 (9010056, 'Masque de Vengeuse Masquée'),
 (9010057, 'Ce masque cache peut-être votre identité, mais il ne vous protègera pas des odeurs de vos énormes flatulences.'),
 (9010058, 'Brassard de Vengeuse Masquée'),
 (9010059, 'Avec ce brassard, il vous sera impossible de vous noyer dans la mer d''Asse.'),
 (9010060, 'Coquille de Vengeuse Masquée'),
 (9010061, 'En plus d''être très solide, Vengeuse Masquée se sert de sa coquille pour transporter tout ce qu''elle vole.'),
 (9010062, 'Collier du YeCh''Ti'),
 (9010063, 'Ce collier illustre bien la créature terrifiante qui sommeille en vous.'),
 (9010064, 'Mitaine du YeCh''Ti'),
 (9010065, 'Tout en vient aux poings à qui n''est pas tendre.'),
 (9010066, 'Bras du YeCh''Ti'),
 (9010067, 'Certains font les malins avec ce bouclier en montrant qu''ils peuvent aussi jouer les gros bras, ça n''est pas pour autant qu''ils ont le droit à de gros chocolats !'),
 (9010068, 'Ceinture de San Jifu'),
 (9010069, 'Sur cette ceinture, une courte phrase est gravée : « J''y étais ». Cela permet à San Jifu de toujours se rappeler d''où elle vient afin de rester lucide.'),
 (9010070, 'Bague de San Jifu'),
 (9010071, 'San Jifu surnomme cette bague "J''y suis", car elle représente tout le parcours effectué jusqu''à présent et tout ce qu''il lui reste encore à découvrir.'),
 (9010072, 'Faux de San Jifu'),
 (9010073, 'On peut lire sur la lame de cette faux "J''y serai". Cela évoque pour San Jifu à la fois le désir de réaliser ses rêves, mais aussi ce vers quoi se dirige tout être vivant : la mort.'),
 (9010074, 'Anneau de Flasho'),
 (9010075, 'Depuis l''existence de Flasho, le rouge est devenu un symbole de rapidité aux yeux des Frigostiens. Pour vous, depuis l''acquisition de cet anneau, le rouge ne fait que rappeler l''état de votre compte bancaire.'),
 (9010076, 'Flashaux'),
 (9010077, 'Faucher vos adversaires sera rapide comme l''éclair, et puissant comme la foudre.'),
 (9010078, 'Boucliéclair de Flasho'),
 (9010079, 'Le forgeron de ce bouclier a eu un éclair de génie.'),
 (9010080, 'Lunettes du Docteur Eggob'),
 (9010081, 'Le Docteur Eggob aurait raconté qu''un prespic bleu qui parle circule dans la forêt enneigée. Autant dire que ces lunettes ne permettront pas de régler vos problèmes de vue...'),
 (9010082, 'Anneau doré du Docteur Eggob'),
 (9010083, 'Faites attention, si vous portez cet anneau, vous risqueriez de le perdre à la moindre blessure.'),
 (9010084, 'Fléau du Docteur Eggob'),
 (9010085, '« Espèce d''idiot, va-t''en ! Avant que je ne te réduise en miettes ! »
